const pptxgen = require('pptxgenjs');
const fs = require('fs');

const pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';

const theme = {
  primary: "03045E",
  secondary: "0077B6",
  accent: "00B4D8",
  light: "CAF0F8",
  bg: "FFFFFF"
};

// Helper for page numbers
function addPageNumber(slide, num) {
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText(String(num).padStart(2, '0'), {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });
}

// Helper for title
function addSlideTitle(slide, title) {
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 0.4, w: 0.1, h: 0.5, fill: { color: theme.accent }
  });
  slide.addText(title, {
    x: 0.7, y: 0.4, w: 8.5, h: 0.5,
    fontSize: 24, fontFace: "Arial", color: theme.primary, bold: true, align: "left", valign: "middle"
  });
}

// --- Slide 1: Cover ---
let s1 = pres.addSlide();
s1.background = { color: theme.primary };
s1.addText("DiaTool-DPO", {
  x: 0.5, y: 1.5, w: 9, h: 1,
  fontSize: 48, fontFace: "Arial", color: "FFFFFF", bold: true
});
s1.addText("Multi-Turn DPO for Tool-Augmented LLMs", {
  x: 0.5, y: 2.5, w: 9, h: 0.6,
  fontSize: 24, fontFace: "Arial", color: theme.accent
});
s1.addText("Enhancing dialogue flow via direct preference optimization with automatic paired trajectory construction.", {
  x: 0.5, y: 3.2, w: 8, h: 1,
  fontSize: 16, fontFace: "Arial", color: "FFFFFF"
});

// --- Slide 2: Problem & Motivation ---
let s2 = pres.addSlide();
s2.background = { color: theme.bg };
addSlideTitle(s2, "SFT Alone Fails to Teach Slot-Filling and Tool Rejection");
addPageNumber(s2, 2);

s2.addText("TA-LLMs trained only with Supervised Fine-Tuning (SFT) struggle with incomplete queries and out-of-scope requests.", {
  x: 0.5, y: 1.2, w: 9, h: 0.8, fontSize: 16, fontFace: "Arial", color: theme.secondary
});

let failureModes = [
  "1. Failing to ask follow-up questions for missing arguments.",
  "2. Making hallucinated tool invocations.",
  "3. Failing to reject inappropriate or out-of-scope tool calls."
];

let currentY = 2.2;
failureModes.forEach(mode => {
  s2.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: currentY, w: 9, h: 0.8,
    fill: { color: "F1F5F9" },
    rectRadius: 0
  });
  s2.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: currentY, w: 0.08, h: 0.8, fill: { color: theme.secondary }
  });
  s2.addText(mode, {
    x: 0.7, y: currentY, w: 8.5, h: 0.8, fontSize: 16, fontFace: "Arial", color: theme.primary, bold: true
  });
  currentY += 1.0;
});


// --- Slide 3: 5-State MDP ---
let s3 = pres.addSlide();
s3.background = { color: theme.bg };
addSlideTitle(s3, "Modeling TA-LLM Dialogue as a 5-State MDP");
addPageNumber(s3, 3);

s3.addText([
  { text: "1. Initial State", options: { bold: true, breakLine: true } },
  { text: "No history. Out-of-scope requests return rejection.", options: { fontSize: 14, color: theme.secondary, breakLine: true } },
  { text: "2. Tool Selected w/o Complete Slots", options: { bold: true, breakLine: true } },
  { text: "Tool identified, required parameters missing. Slot-filling occurs.", options: { fontSize: 14, color: theme.secondary, breakLine: true } },
  { text: "3. Tool Selected w/ Complete Slots", options: { bold: true, breakLine: true } },
  { text: "Selection and arguments determined.", options: { fontSize: 14, color: theme.secondary, breakLine: true } },
  { text: "4. Wait for Tool Response", options: { bold: true, breakLine: true } },
  { text: "Call executed, awaiting results.", options: { fontSize: 14, color: theme.secondary, breakLine: true } },
  { text: "5. Complete", options: { bold: true } }
], {
  x: 0.5, y: 1.2, w: 4.5, h: 3.5, fontSize: 16, fontFace: "Arial", color: theme.primary, paraSpaceAfter: 6
});

s3.addImage({ path: "imgs/figure_1.jpg", x: 5.2, y: 1.2, w: 4.5, h: 3.5, sizing: { type: 'contain', w: 4.5, h: 3.5 } });

// --- Slide 4: Three Query Types ---
let s4 = pres.addSlide();
s4.background = { color: theme.bg };
addSlideTitle(s4, "Three Query Types Define Distinct State Trajectories");
addPageNumber(s4, 4);

s4.addTable([
  [
    { text: "Query Type", options: { fill: { color: theme.primary }, color: "FFFFFF", bold: true, align: "center", fontSize: 16 } },
    { text: "State Trajectory", options: { fill: { color: theme.primary }, color: "FFFFFF", bold: true, align: "center", fontSize: 16 } },
    { text: "Description", options: { fill: { color: theme.primary }, color: "FFFFFF", bold: true, align: "left", fontSize: 16 } }
  ],
  [
    { text: "Type 1", options: { align: "center", bold: true, color: theme.primary } },
    { text: "1 → 3 → 4 → 5", options: { align: "center", color: theme.secondary } },
    { text: "Query contains all required arguments. No slot-filling needed.", options: { align: "left" } }
  ],
  [
    { text: "Type 2", options: { align: "center", bold: true, color: theme.primary } },
    { text: "1 → (2*N) → 3 → 4 → 5", options: { align: "center", color: theme.secondary } },
    { text: "Query lacks arguments. Slot-filling QA repeats N times.", options: { align: "left" } }
  ],
  [
    { text: "Type 3", options: { align: "center", bold: true, color: theme.primary } },
    { text: "1 → 1", options: { align: "center", color: theme.secondary } },
    { text: "Requested functionality unavailable. Tool call rejected.", options: { align: "left" } }
